var e={macroDesigner:{intro:{t:0,b:{t:2,i:[{t:3}],s:`G-code를 오프라인으로 시뮬레이션하세요 - 프로그램을 붙여넣거나 작성하면 프린터를 건드리지 않고도 툴헤드 경로, 경계 상자, 이동/압출 합계, 예상 소요 시간을 볼 수 있습니다. 내장 매크로 라이브러리도 참고용으로 둘러보세요.`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`도움말`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Macro Designer 소개`}},close:{t:0,b:{t:2,i:[{t:3}],s:`닫기`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`사용 방법`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`에디터에 G-code를 입력하거나 붙여넣으세요 (시작용 샘플 사각형이 미리 로드됩니다).`}},{t:0,b:{t:2,i:[{t:3}],s:`Simulate를 누르면 2D 경로와 통계가 갱신됩니다.`}},{t:0,b:{t:2,i:[{t:3}],s:`실선은 압출 이동이고, 흐린 점선은 이동(travel)입니다.`}},{t:0,b:{t:2,i:[{t:3}],s:`매크로 라이브러리를 둘러보고 하나를 Insert해 그 명령으로 시작하세요.`}}],topics:{simulator:{title:{t:0,b:{t:2,i:[{t:3}],s:`시뮬레이터`}},body:{t:0,b:{t:2,i:[{t:3}],s:`가상 툴헤드에서 프로그램을 실행합니다: G0/G1 이동, G90/G91(절대/상대), M82/M83(압출기 모드), G92(위치 설정), G28(홈 → 원점). 경로, 경계 상자, 총 이동량과 압출량, 피드레이트 기반의 대략적인 예상 시간, 그리고 명령별 타임라인을 보고합니다. 프린터로는 아무것도 전송되지 않습니다.`}}},motion:{title:{t:0,b:{t:2,i:[{t:3}],s:`경로 & 시간`}},body:{t:0,b:{t:2,i:[{t:3}],s:`2D 화면은 XY 경로입니다(Z는 경계에 포함됨). 예상 시간은 각 이동의 길이를 피드레이트로 나눈 값으로, 가속도를 무시하므로 정확한 출력 시간이 아니라 대략적인 하한값입니다. 시뮬레이터가 모델링하지 않는 명령(예: M-code, 상위 레벨 매크로)은 경고로 표시되고 건너뜁니다.`}}},macros:{title:{t:0,b:{t:2,i:[{t:3}],s:`매크로 라이브러리`}},body:{t:0,b:{t:2,i:[{t:3}],s:`자주 쓰이는 Klipper 매크로의 이름, 기능, 필요한 config 섹션을 모은 참고 모음입니다. "Insert"는 매크로의 상위 레벨 명령을 에디터에 시작점으로 넣어 줍니다 - 이 명령은 프린터에서 추가로 확장됩니다(전체 Jinja/매크로 확장 기능 예정).`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`용어집`}},body:{t:0,b:{static:``,t:2,i:[]}}}},glossary:{gcode:{term:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},def:{t:0,b:{t:2,i:[{t:3}],s:`프린터가 한 줄씩 실행하는 동작 언어입니다(이동, 온도, 팬 등).`}}},feedrate:{term:{t:0,b:{t:2,i:[{t:3}],s:`피드레이트 (F)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`mm/min 단위의 이동 속도 - F1200은 20 mm/s입니다. 각 이동이 얼마나 빠르게 실행될지 정합니다.`}}},macro:{term:{t:0,b:{t:2,i:[{t:3}],s:`매크로`}},def:{t:0,b:{t:2,i:[{t:3}],s:`G-code 시퀀스로 확장되는, 이름이 붙은 재사용 명령(예: QUAD_GANTRY_LEVEL)입니다.`}}}}},editor:{label:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},simulate:{t:0,b:{t:2,i:[{t:3}],s:`시뮬레이션`}},simulating:{t:0,b:{t:2,i:[{t:3}],s:`시뮬레이션 중…`}},sample:{t:0,b:{t:2,i:[{t:3}],s:`샘플 불러오기`}},clear:{t:0,b:{t:2,i:[{t:3}],s:`지우기`}}},library:{label:{t:0,b:{t:2,i:[{t:3}],s:`내장 매크로`}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:`매크로 둘러보기…`}},insert:{t:0,b:{t:2,i:[{t:3}],s:`에디터에 삽입`}},requires:{t:0,b:{t:2,i:[{t:3,v:`필요: `},{t:4,k:`sections`}]}},none:{t:0,b:{t:2,i:[{t:3}],s:`-`}}},result:{title:{t:0,b:{t:2,i:[{t:3}],s:`시뮬레이션`}},moves:{t:0,b:{t:2,i:[{t:3,v:`이동 `},{t:4,k:`count`},{t:3,v:`개`}]}},distance:{t:0,b:{t:2,i:[{t:3,v:`이동 `},{t:4,k:`mm`},{t:3,v:` mm`}]}},extrude:{t:0,b:{t:2,i:[{t:3,v:`압출 `},{t:4,k:`mm`},{t:3,v:` mm`}]}},time:{t:0,b:{t:2,i:[{t:3,v:`~`},{t:4,k:`s`},{t:3,v:` s`}]}},bounds:{t:0,b:{t:2,i:[{t:3}],s:`경계`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`시뮬레이션할 이동이 없습니다.`}},timeAccel:{t:0,b:{t:2,i:[{t:3}],s:`(가속도 반영)`}},timeConstant:{t:0,b:{t:2,i:[{t:3}],s:`(제한 없음)`}}},path:{title:{t:0,b:{t:2,i:[{t:3}],s:`툴헤드 경로 (XY)`}},noPath:{t:0,b:{t:2,i:[{t:3}],s:`경로를 보려면 시뮬레이션을 실행하세요.`}}},explain:{title:{t:0,b:{t:2,i:[{t:3}],s:`이 매크로 설명`}},travel:{t:0,b:{t:2,i:[{t:3,v:`X`},{t:4,k:`x`},{t:3,v:` Y`},{t:4,k:`y`},{t:3,v:`로 `},{t:4,k:`f`},{t:3,v:` mm/min 속도로 빠른 이동`}]}},print:{t:0,b:{t:2,i:[{t:3,v:`출력 이동 - X`},{t:4,k:`x`},{t:3,v:` Y`},{t:4,k:`y`},{t:3,v:`까지 `},{t:4,k:`d`},{t:3,v:` mm 동안 `},{t:4,k:`e`},{t:3,v:` mm 압출, `},{t:4,k:`f`},{t:3,v:` mm/min`}]}},retract:{t:0,b:{t:2,i:[{t:4,k:`e`},{t:3,v:` mm 리트랙트`}]}},prime:{t:0,b:{t:2,i:[{t:3,v:`제자리에서 `},{t:4,k:`e`},{t:3,v:` mm 압출`}]}},noMove:{t:0,b:{t:2,i:[{t:3}],s:`이동 없음`}},absXYZ:{t:0,b:{t:2,i:[{t:3}],s:`절대 위치 지정으로 전환 (G90)`}},relXYZ:{t:0,b:{t:2,i:[{t:3}],s:`상대 위치 지정으로 전환 (G91)`}},absE:{t:0,b:{t:2,i:[{t:3}],s:`절대 압출로 전환 (M82)`}},relE:{t:0,b:{t:2,i:[{t:3}],s:`상대 압출로 전환 (M83)`}},setPos:{t:0,b:{t:2,i:[{t:3}],s:`현재 위치 설정 (G92)`}},home:{t:0,b:{t:2,i:[{t:3}],s:`축 홈 (G28) → 원점`}},abs:{t:0,b:{t:2,i:[{t:3}],s:`ABS`}},rel:{t:0,b:{t:2,i:[{t:3}],s:`REL`}},cum:{t:0,b:{t:2,i:[{t:3,v:`누적: `},{t:4,k:`d`},{t:3,v:` mm · `},{t:4,k:`e`},{t:3,v:` mm · ~`},{t:4,k:`s`},{t:3,v:` s`}]}},note:{t:0,b:{t:2,i:[{t:3}],s:`반복문과 조건문은 프린터가 처리하는 방식대로 확장됩니다. 실시간 프린터 상태가 필요한 매크로는 리터럴 미리보기로 대체됩니다.`}}},timeline:{title:{t:0,b:{t:2,i:[{t:3}],s:`타임라인`}},line:{t:0,b:{t:2,i:[{t:3}],s:`줄`}},cmd:{t:0,b:{t:2,i:[{t:3}],s:`명령`}},action:{t:0,b:{t:2,i:[{t:3}],s:`동작`}}},warnings:{title:{t:0,b:{t:2,i:[{t:3}],s:`경고`}}},live:{label:{t:0,b:{t:2,i:[{t:3}],s:`프린터에서`}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:`설치된 매크로 중 하나를 선택하세요…`}},hint:{t:0,b:{t:2,i:[{t:3,v:`프린터에서 매크로 `},{t:4,k:`n`},{t:3,v:`개를 찾았습니다 - 하나를 선택하면 해당 G-code를 불러와 시뮬레이션합니다.`}]}},unreachable:{t:0,b:{t:2,i:[{t:3}],s:`프린터에 연결할 수 없습니다 - 설치된 매크로를 불러오려면 연결하세요.`}},params:{t:0,b:{t:2,i:[{t:3}],s:`매크로 파라미터`}}},limits:{title:{t:0,b:{t:2,i:[{t:3}],s:`범위 초과 / 속도 초과`}},oob:{t:0,b:{t:2,i:[{t:3,v:`줄 `},{t:4,k:`line`},{t:3,v:`: `},{t:4,k:`axis`},{t:3,v:`=`},{t:4,k:`value`},{t:3,v:`가 빌드 영역(`},{t:4,k:`min`},{t:3,v:`…`},{t:4,k:`max`},{t:3,v:` mm)을 벗어납니다.`}]}},overSpeed:{t:0,b:{t:2,i:[{t:3,v:`줄 `},{t:4,k:`line`},{t:3,v:`: `},{t:4,k:`value`},{t:3,v:` mm/s가 프린터의 `},{t:4,k:`limit`},{t:3,v:` mm/s 한계를 초과합니다(Klipper가 제한합니다).`}]}},buildArea:{t:0,b:{t:2,i:[{t:3,v:`빌드 영역 `},{t:4,k:`x`},{t:3,v:`×`},{t:4,k:`y`},{t:3,v:` mm`}]}}},lint:{title:{t:0,b:{t:2,i:[{t:3,v:`매크로 린터 - 발견 `},{t:4,k:`n`},{t:3,v:`건`}]}},rule:{gcode_state_unbalanced:{msg:{t:0,b:{t:2,i:[{t:3}],s:`RESTORE_GCODE_STATE 없이 SAVE_GCODE_STATE만 있습니다 - 저장된 위치 지정/압출기 모드가 복원되지 않습니다.`}},fix:{t:0,b:{t:2,i:[{t:3}],s:`RESTORE_GCODE_STATE를 추가하세요(또는 SAVE를 제거하세요).`}}},ends_relative:{msg:{t:0,b:{t:2,i:[{t:3}],s:`매크로가 상대 모드(G91/M83)로 끝납니다 - 다음 명령이 상대적으로 이동합니다.`}},fix:{t:0,b:{t:2,i:[{t:3}],s:`마지막에 G90 / M82를 추가하거나, 이동을 SAVE_GCODE_STATE … RESTORE_GCODE_STATE로 감싸세요.`}}},extrude_before_home:{msg:{t:0,b:{t:2,i:[{t:3}],s:`G28 전에 압출 이동이 발생합니다 - 콜드 또는 비홈 상태 압출 위험이 있습니다.`}},fix:{t:0,b:{t:2,i:[{t:3}],s:`압출 전에 홈(G28)하고 핫엔드를 가열하세요.`}}}}},heat:{colorBy:{t:0,b:{t:2,i:[{t:3}],s:`색상 기준`}},none:{t:0,b:{t:2,i:[{t:3}],s:`단색`}},speed:{t:0,b:{t:2,i:[{t:3}],s:`속도`}},extrude:{t:0,b:{t:2,i:[{t:3}],s:`압출`}},legendSpeed:{t:0,b:{t:2,i:[{t:3}],s:`속도 (mm/s)`}},legendExtrude:{t:0,b:{t:2,i:[{t:3}],s:`압출 (mm/s)`}}},compare:{title:{t:0,b:{t:2,i:[{t:3}],s:`비교 (A / B)`}},hint:{t:0,b:{t:2,i:[{t:3}],s:`두 번째 프로그램(B)을 시뮬레이션해 현재 결과(A)와 비교합니다.`}},copyA:{t:0,b:{t:2,i:[{t:3}],s:`A → B 복사`}},run:{t:0,b:{t:2,i:[{t:3}],s:`비교`}},running:{t:0,b:{t:2,i:[{t:3}],s:`비교 중…`}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:`B 프로그램을 붙여넣거나 작성하세요…`}},editorB:{t:0,b:{t:2,i:[{t:3}],s:`프로그램 B`}},overlay:{t:0,b:{t:2,i:[{t:3}],s:`A 대 B 경로 오버레이`}},legendA:{t:0,b:{t:2,i:[{t:3}],s:`A`}},legendB:{t:0,b:{t:2,i:[{t:3}],s:`B`}},lintDelta:{t:0,b:{t:2,i:[{t:3}],s:`린터 차이`}},lintSame:{t:0,b:{t:2,i:[{t:3}],s:`두 프로그램의 린터 발견 항목이 동일합니다.`}},onlyA:{t:0,b:{t:2,i:[{t:3}],s:`A에만 있음`}},onlyB:{t:0,b:{t:2,i:[{t:3}],s:`B에만 있음`}},row:{moves:{t:0,b:{t:2,i:[{t:3}],s:`이동`}},distance:{t:0,b:{t:2,i:[{t:3}],s:`거리 (mm)`}},extrude:{t:0,b:{t:2,i:[{t:3}],s:`압출 (mm)`}},time:{t:0,b:{t:2,i:[{t:3}],s:`시간 (s)`}}}},scaffold:{title:{t:0,b:{t:2,i:[{t:3}],s:`START / END_PRINT 생성`}},hint:{t:0,b:{t:2,i:[{t:3}],s:`이 프린터에 맞춘 START_PRINT와 END_PRINT를 만듭니다 - 홈잉, 실제 보유한 레벨링, 메시 단계, 실제 빌드 영역 안의 프라임/파킹 위치를 반영합니다.`}},generate:{t:0,b:{t:2,i:[{t:3}],s:`생성`}},generating:{t:0,b:{t:2,i:[{t:3}],s:`생성 중…`}},loadEditor:{t:0,b:{t:2,i:[{t:3}],s:`에디터에 불러오기`}},writeTitle:{t:0,b:{t:2,i:[{t:3}],s:`config에 쓰기`}},target:{t:0,b:{t:2,i:[{t:3}],s:`대상 파일`}},append:{t:0,b:{t:2,i:[{t:3}],s:`config에 추가…`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`추가 확인`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`취소`}},appending:{t:0,b:{t:2,i:[{t:3}],s:`쓰는 중…`}},writeNote:{t:0,b:{t:2,i:[{t:3}],s:`확인 단계를 거쳐 두 매크로를 선택한 파일에 추가합니다 - 먼저 백업이 생성되며 출력 중에는 쓰기가 거부됩니다. 같은 이름의 매크로가 이미 있으면 거부됩니다.`}},saved:{t:0,b:{t:2,i:[{t:4,k:`file`},{t:3,v:`에 저장됨.`}]}},savedBackup:{t:0,b:{t:2,i:[{t:4,k:`file`},{t:3,v:`에 저장됨 (백업: `},{t:4,k:`backup`},{t:3,v:`). 적용하려면 펌웨어를 재시작하세요.`}]}},note:{kinematics:{t:0,b:{t:2,i:[{t:3,v:`키네매틱스: `},{t:4,k:`k`},{t:3,v:`.`}]}},bounds:{t:0,b:{t:2,i:[{t:3,v:`빌드 영역 X `},{t:4,k:`x0`},{t:3,v:`-`},{t:4,k:`x1`},{t:3,v:`, Y `},{t:4,k:`y0`},{t:3,v:`-`},{t:4,k:`y1`},{t:3,v:` (프라임/파킹이 안쪽에 맞춰짐).`}]}},leveling_qgl:{t:0,b:{t:2,i:[{t:3}],s:`quad_gantry_level 감지됨 -> QUAD_GANTRY_LEVEL 추가됨.`}},leveling_ztilt:{t:0,b:{t:2,i:[{t:3}],s:`z_tilt 감지됨 -> Z_TILT_ADJUST 추가됨.`}},leveling_none:{t:0,b:{t:2,i:[{t:3}],s:`quad_gantry_level / z_tilt가 설정되지 않음 - 자리표시자를 남겼습니다.`}},mesh:{t:0,b:{t:2,i:[{t:3}],s:`bed_mesh 감지됨 -> BED_MESH_CALIBRATE 추가됨.`}},no_bed:{t:0,b:{t:2,i:[{t:3}],s:`가열 베드 없음 - 베드 가열 단계가 생략됨.`}}}},flow:{title:{t:0,b:{t:2,i:[{t:3}],s:`유량 검사 (핫엔드 한계)`}},hint:{t:0,b:{t:2,i:[{t:3}],s:`카탈로그에서 핫엔드를 선택하면 모든 출력 이동이 실제 멜트존 한계와 대조됩니다 - 유량이 초과되는 매크로를 출력 전에 잡아냅니다.`}},hotend:{t:0,b:{t:2,i:[{t:3}],s:`핫엔드`}},pick:{t:0,b:{t:2,i:[{t:3}],s:`핫엔드를 선택하세요…`}},diameter:{t:0,b:{t:2,i:[{t:3}],s:`Ø mm`}},ok:{t:0,b:{t:2,i:[{t:3,v:`모든 출력 이동이 `},{t:4,k:`ceiling`},{t:3,v:` mm³/s 한계 이내입니다.`}]}},overTitle:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:`개 이동이 `},{t:4,k:`ceiling`},{t:3,v:` mm³/s 한계를 초과합니다:`}]}},overLine:{t:0,b:{t:2,i:[{t:3,v:`줄 `},{t:4,k:`line`},{t:3,v:`: `},{t:4,k:`flow`},{t:3,v:` mm³/s`}]}}}}};export{e as default};